1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	};
7	
8	const COMPONENT_BASE_PREMIUM = 25;
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_PREMIUM = 60;
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	
13	const FIRST_INSURANCE_SURCHARGE = 0.1;
14	const CURSE_SURCHARGE = 0.5;
15	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
16	const HIGH_ENCHANTMENT_THRESHOLD = 5;
17	const LOYALTY_DISCOUNT = 0.2;
18	const LOYALTY_YEARS_THRESHOLD = 2;
19	const FOLLOWUP_CONTRACT_DISCOUNT = 0.15;
20	
21	const INSURANCE_VALUES: Record<string, number> = {
22	  sword: 1000,
23	  amulet: 600,
24	  rune: 250,
25	  moonstone: 250,
26	};
27	
28	const DEDUCTIBLE = 100;
29	const CAP_MULTIPLIER = 2;
30	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
31	const HALF_REIMBURSEMENT = 0.5;
32	const FULL_REIMBURSEMENT = 1;
33	
34	interface Item {
35	  type: string;
36	  cursed?: boolean;
37	  enchantment?: number;
38	}
39	
40	interface QuoteStep {
41	  op: "quote";
42	  items: Item[];
43	}
44	
45	interface Damage {
46	  itemType: string;
47	  amount: number;
48	}
49	
50	interface ClaimStep {
51	  op: "claim";
52	  policy: number;
53	  incident: { cause: string; damages: Damage[] };
54	}
55	
56	type Step = QuoteStep | ClaimStep;
57	
58	interface Customer {
59	  yearsWithMHPCO: number;
60	}
61	
62	interface Scenario {
63	  customer: Customer;
64	  steps: Step[];
65	}
66	
67	interface QuoteResult {
68	  premium: number;
69	}
70	
71	interface ClaimResult {
72	  payout: number;
73	  remainingCap: number;
74	}
75	
76	type StepResult = QuoteResult | ClaimResult;
77	
78	interface ScenarioResult {
79	  results: StepResult[];
80	}
81	
82	const componentGroupBase = (count: number): number =>
83	  count === COMPONENT_BLOCK_SIZE
84	    ? COMPONENT_BLOCK_PREMIUM
85	    : count * COMPONENT_BASE_PREMIUM;
86	
87	const countByType = (items: Item[]): Map<string, number> => {
88	  const counts = new Map<string, number>();
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	  return counts;
93	};
94	
95	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
96	
97	const isHighEnchantment = (item: Item): boolean =>
98	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
99	
100	interface PricedUnit {
101	  base: number;
102	  surcharges: number[];
103	}
104	
105	const mainItemUnit = (item: Item): PricedUnit => {
106	  const base = BASE_PREMIUMS[item.type];
107	  const surcharges: number[] = [];
108	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
109	  if (isHighEnchantment(item)) surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
110	  return { base, surcharges };
111	};
112	
113	const componentUnit = (count: number): PricedUnit => ({
114	  base: componentGroupBase(count),
115	  surcharges: [],
116	});
117	
118	const pricedUnits = (items: Item[]): PricedUnit[] => {
119	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
120	
121	  const components = items.filter(isComponent);
122	  const componentUnits = [...countByType(components).values()].map(componentUnit);
123	
124	  return [...mainUnits, ...componentUnits];
125	};
126	
127	const unitTotal = (unit: PricedUnit): number =>
128	  unit.base +
129	  unit.base * FIRST_INSURANCE_SURCHARGE +
130	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
131	
132	// Policy-level discount fractions applied to the policy base (sum of unit bases).
133	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
134	// contract discount) can be added here without touching per-item pricing.
135	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
136	  const fractions: number[] = [];
137	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
138	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
139	  return fractions;
140	};
141	
142	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
143	  const units = pricedUnits(items);
144	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
145	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
146	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
147	    (sum, fraction) => sum + policyBase * fraction,
148	    0,
149	  );
150	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
151	};
152	
153	interface Policy {
154	  items: Item[];
155	  cap: number;
156	}
157	
158	const createPolicy = (items: Item[]): Policy => {
159	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
160	  return { items, cap: insuranceSum * CAP_MULTIPLIER };
161	};
162	
163	// Fraction of a damage amount the policy reimburses, before the deductible.
164	// Coverage clauses (e.g. dragon-material full reimbursement) will add branches here.
165	const reimbursementRate = (item: Item | undefined): number =>
166	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
167	    ? HALF_REIMBURSEMENT
168	    : FULL_REIMBURSEMENT;
169	
170	const reimbursedAmount = (item: Item | undefined, amount: number): number =>
171	  amount * reimbursementRate(item);
172	
173	const damagePayout = (policy: Policy, damage: Damage): number => {
174	  const item = policy.items.find((candidate) => candidate.type === damage.itemType);
175	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
176	};
177	
178	const processClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
179	  const payout = damages.reduce((sum, damage) => sum + damagePayout(policy, damage), 0);
180	  return { payout, remainingCap: policy.cap - payout };
181	};
182	
183	export const runScenario = (scenario: Scenario): ScenarioResult => {
184	  const policies: Policy[] = [];
185	  let quoteCount = 0;
186	
187	  const handleQuote = (step: QuoteStep): QuoteResult => {
188	    const isFollowUp = quoteCount > 0;
189	    quoteCount += 1;
190	    policies.push(createPolicy(step.items));
191	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
192	  };
193	
194	  const handleClaim = (step: ClaimStep): ClaimResult =>
195	    processClaim(policies[step.policy], step.incident.damages);
196	
197	  const results = scenario.steps.map((step): StepResult =>
198	    step.op === "quote" ? handleQuote(step) : handleClaim(step),
199	  );
200	  return { results };
201	};
